// Per-conversation memory (survives between messages via workflow static data).
const msg = $input.first().json.message;
if (!msg || !msg.text) return []; // ignore stickers/photos for the demo
const chatId = msg.chat.id;
const text = String(msg.text).trim();
const from = msg.from?.first_name || 'Parent';

const staticData = $getWorkflowStaticData('global');
staticData.chats = staticData.chats || {};
const key = 'chat_' + chatId;
const state = staticData[key] || { data: {}, history: [] };

state.history = state.history || [];
state.history.push({ role: 'parent', text });
while (state.history.length > 8) state.history.shift();
staticData[key] = state;

const KB = [
  'Courses: IELTS Preparation (intensive & standard), TOEFL Preparation, Business English.',
  'Class size: max 12 students. Teachers are certified, IELTS 8.0+.',
  'Free placement test every Saturday morning.',
  'Tuition: from 6,000,000 VND for an 8-week course (exact quote given by a counselor).',
  'Campuses: District 1 and Thu Duc (Ho Chi Minh City).',
  'Hours: 8:00-20:00 Mon-Sat. Hotline: 0900 000 000.'
].join('\n');

const system = [
  'You are the friendly enrollment assistant of an English training school, chatting with parents on Telegram.',
  'Knowledge base:',
  KB,
  '',
  'Rules:',
  '- Answer questions clearly and briefly, using ONLY the knowledge base. If something is not there, say a counselor will confirm it.',
  '- When the parent shows enrollment intent (wants to register, asks how to sign up), collect: full name, phone number, and course of interest. Ask for ONE missing item at a time, warmly.',
  '- Never invent prices beyond the "from 6,000,000 VND" line. Never promise discounts or schedules.',
  '- Reply in the parent\'s language (Vietnamese or English).',
  'Return ONLY a single JSON object:',
  '- Normal answer or still collecting: {"action":"reply","text":"<your reply>","collected":{...}}',
  '- When name AND phone AND course are all known: {"action":"submit","text":"<warm confirmation that a counselor will contact them soon>","lead":{"name":"...","phone":"...","course":"...","note":"<anything else the parent said that matters>"}}'
].join('\n');

const user = [
  'Collected so far: ' + JSON.stringify(state.data || {}),
  'Recent conversation:',
  ...state.history.map((h) => h.role + ': ' + h.text)
].join('\n');

return [{ json: { chatId, from, text, key, state, system, user } }];

// Schema check + merge AI's collected info into conversation state.
const turn = $('Prepare turn').first().json;
const ai = $('AI chat turn').first().json;

const text = (ai.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('');
let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  return [{ json: { chatId: turn.chatId, action: 'reply', replyText: 'Sorry, I had trouble just now — please try again in a moment.' } }];
}

const staticData = $getWorkflowStaticData('global');
staticData.chats = staticData.chats || {};
const state = staticData.chats[turn.key] || { data: {}, history: [] };
state.data = { ...(state.data || {}), ...(parsed.collected || {}) };

let action = parsed.action === 'submit' ? 'submit' : 'reply';
const lead = parsed.lead || {};
// Only submit when we truly have the required trio.
if (action === 'submit' && (!lead.name || !lead.phone || !lead.course)) {
  action = 'reply';
}

if (action === 'submit') {
  staticData.chats[turn.key] = { data: {}, history: [] }; // reset for the next parent
} else {
  staticData.chats[turn.key] = state;
}

const replyText = action === 'submit'
  ? (parsed.text || 'Thank you! A counselor will contact you soon.')
  : (parsed.text || 'Could you tell me a bit more?');

return [{ json: {
  chatId: turn.chatId,
  action,
  replyText,
  lead: action === 'submit'
    ? {
        name: String(lead.name).slice(0, 200),
        phone: String(lead.phone).slice(0, 40),
        course: String(lead.course).slice(0, 100),
        note: String(lead.note || turn.text).slice(0, 1000),
        from: turn.from
      }
    : null
} }];
